const COLORS = {
  ink: '#020910',
  navy: '#061722',
  panel: '#071D29',
  panel2: '#0A2531',
  line: '#244A59',
  lineBright: '#58D9DE',
  cyan: '#6FF7F2',
  cyanDeep: '#23AFC1',
  mint: '#78F7C8',
  amber: '#FFCA76',
  red: '#FF8D88',
  text: '#E8FCFB',
  textMuted: '#7FA5AE',
  textDim: '#4E737E',
};

const clamp = (value: number) => Math.max(0, Math.min(1, value));

const reveal = (
  frame: number,
  start: number,
  end: number,
  easing: (value: number) => number = Easing.out(Easing.cubic),
) =>
  interpolate(frame, [start, end], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing,
  });

const lerp = (from: number, to: number, progress: number) =>
  from + (to - from) * progress;

const digit = (value: number) =>
  Math.max(0, Math.round(value)).toLocaleString('en-US');

type TimelineState = {
  progress: number;
  complete: boolean;
};

// One continuous data story: initialize, grow to the final snapshot, then hold.
// No reset phases are used anywhere in the 900-frame composition.
const getTimelineState = (frame: number): TimelineState => {
  const progress = reveal(frame, 132, 690, Easing.linear);
  return {progress, complete: progress >= 1};
};

type PanelShellProps = {
  x: number;
  y: number;
  width: number;
  height: number;
  start: number;
  origin?: 'left' | 'right' | 'center';
  accent?: boolean;
};

const PanelShell: React.FC<PanelShellProps> = ({
  x,
  y,
  width,
  height,
  start,
  origin = 'left',
  accent = false,
}) => {
  const frame = useCurrentFrame();
  const progress = reveal(frame, start, start + 42);
  const sheen = reveal(frame, start + 8, start + 32);

  return (
    <div
      style={{
        position: 'absolute',
        left: x,
        top: y,
        width,
        height,
        boxSizing: 'border-box',
        border: `1px solid ${accent ? 'rgba(111,247,242,0.36)' : 'rgba(69,129,145,0.36)'}`,
        background:
          'linear-gradient(145deg, rgba(12,46,60,0.72), rgba(4,17,25,0.52) 62%, rgba(3,13,20,0.66))',
        transform: `scaleX(${progress})`,
        transformOrigin: origin,
        opacity: 0.12 + progress * 0.88,
        overflow: 'hidden',
        boxShadow: accent
          ? 'inset 0 0 45px rgba(66,214,220,0.035), 0 0 24px rgba(47,191,204,0.04)'
          : 'inset 0 0 36px rgba(66,214,220,0.025)',
      }}
    >
      <div
        style={{
          position: 'absolute',
          inset: 0,
          opacity: progress * 0.24,
          backgroundImage:
            'linear-gradient(rgba(90,208,214,0.045) 1px, transparent 1px), linear-gradient(90deg, rgba(90,208,214,0.035) 1px, transparent 1px)',
          backgroundSize: '48px 48px',
        }}
      />
      <div
        style={{
          position: 'absolute',
          top: 0,
          bottom: 0,
          width: 90,
          left: origin === 'right' ? 0 : undefined,
          right: origin === 'right' ? undefined : 0,
          opacity: (1 - sheen) * progress,
          background:
            'linear-gradient(90deg, transparent, rgba(102,247,242,0.22), transparent)',
          filter: 'blur(8px)',
        }}
      />
    </div>
  );
};

