type Hub = {id: string; code: string; x: number; y: number; labelDx: number; labelDy: number};

const HUBS: Hub[] = [
  {id: 'los-angeles', code: 'LAX', x: 221.28971, y: 147.741605, labelDx: -13, labelDy: -15},
  {id: 'new-york', code: 'NYC', x: 330.170783, y: 128.465605, labelDx: 10, labelDy: -13},
  {id: 'rotterdam', code: 'RTM', x: 509.67697, y: 96.712946, labelDx: 10, labelDy: -12},
  {id: 'dubai', code: 'DXB', x: 633.804797, y: 173.462033, labelDx: 10, labelDy: -10},
  {id: 'singapore', code: 'SIN', x: 759.068245, y: 242.512345, labelDx: 10, labelDy: 18},
  {id: 'shanghai', code: 'SHA', x: 789.073661, y: 155.941567, labelDx: -31, labelDy: -14},
  {id: 'tokyo', code: 'TYO', x: 827.288966, y: 142.98976, labelDx: 12, labelDy: -10},
  {id: 'sydney', code: 'SYD', x: 856.645527, y: 344.557243, labelDx: 11, labelDy: 18},
  {id: 'sao-paulo', code: 'SAO', x: 386.655927, y: 314.562332, labelDx: 10, labelDy: 18},
];

const hubById = (id: string) => HUBS.find((hub) => hub.id === id) as Hub;

type Route = {
  from: string;
  to: string;
  lift: number;
  delay: number;
  color: string;
};

const ROUTES: Route[] = [
  {from: 'los-angeles', to: 'new-york', lift: 46, delay: 0, color: COLORS.cyan},
  {from: 'new-york', to: 'rotterdam', lift: 72, delay: 10, color: COLORS.cyan},
  {from: 'rotterdam', to: 'dubai', lift: 52, delay: 20, color: COLORS.mint},
  {from: 'dubai', to: 'singapore', lift: 58, delay: 30, color: COLORS.amber},
  {from: 'singapore', to: 'shanghai', lift: 44, delay: 40, color: COLORS.cyan},
  {from: 'shanghai', to: 'tokyo', lift: 30, delay: 50, color: COLORS.cyan},
  {from: 'singapore', to: 'sydney', lift: 48, delay: 60, color: COLORS.mint},
  {from: 'sao-paulo', to: 'rotterdam', lift: 110, delay: 70, color: COLORS.amber},
  {from: 'los-angeles', to: 'tokyo', lift: 118, delay: 80, color: '#80AFFF'},
];

const routePath = (route: Route) => {
  const from = hubById(route.from);
  const to = hubById(route.to);
  const cx = (from.x + to.x) / 2;
  const cy = (from.y + to.y) / 2 - route.lift;
  return `M${from.x.toFixed(2)},${from.y.toFixed(2)} Q${cx.toFixed(2)},${cy.toFixed(2)} ${to.x.toFixed(2)},${to.y.toFixed(2)}`;
};

const pointOnRoute = (route: Route, t: number) => {
  const from = hubById(route.from);
  const to = hubById(route.to);
  const cx = (from.x + to.x) / 2;
  const cy = (from.y + to.y) / 2 - route.lift;
  const inv = 1 - t;
  return {
    x: inv * inv * from.x + 2 * inv * t * cx + t * t * to.x,
    y: inv * inv * from.y + 2 * inv * t * cy + t * t * to.y,
  };
};

