const Atmosphere: React.FC = () => {
  const frame = useCurrentFrame();
  const entrance = reveal(frame, 0, 56, Easing.out(Easing.quad));
  const sweep = reveal(frame, 0, 420, Easing.inOut(Easing.cubic));
  const sweepOpacity = 1 - reveal(frame, 360, 440);
  const breathing = 0.72 + 0.28 * reveal(frame, 0, 260, Easing.out(Easing.quad));
  return (
    <AbsoluteFill
      style={{
        background: COLORS.ink,
        overflow: 'hidden',
      }}
    >
      <div
        style={{
          position: 'absolute',
          inset: 0,
          opacity: entrance,
          background:
            `radial-gradient(circle at 67% 34%, rgba(17,123,145,${0.18 + breathing * 0.07}), transparent 42%), radial-gradient(circle at 22% 64%, rgba(13,82,106,0.18), transparent 40%), linear-gradient(130deg, #02080E 0%, #061722 52%, #020A11 100%)`,
        }}
      />
      <div
        style={{
          position: 'absolute',
          inset: 0,
          opacity: entrance * 0.24,
          backgroundImage:
            'linear-gradient(rgba(55,141,157,0.055) 1px, transparent 1px), linear-gradient(90deg, rgba(55,141,157,0.045) 1px, transparent 1px)',
          backgroundSize: '72px 72px',
          maskImage: 'radial-gradient(circle at center, black, transparent 88%)',
        }}
      />
      <div
        style={{
          position: 'absolute',
          top: -100,
          bottom: -100,
          width: 260,
          left: sweep * 2220 - 260,
          transform: 'skewX(-12deg)',
          opacity: entrance * 0.12 * sweepOpacity,
          background: 'linear-gradient(90deg, transparent, rgba(99,239,240,0.24), transparent)',
          filter: 'blur(30px)',
        }}
      />
      <div
        style={{
          position: 'absolute',
          inset: 0,
          opacity: 0.21,
          background: 'repeating-linear-gradient(0deg, rgba(255,255,255,0.018) 0px, rgba(255,255,255,0.018) 1px, transparent 1px, transparent 4px)',
        }}
      />
    </AbsoluteFill>
  );
};

